using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class TimelineEditorOperations
{
    private readonly ActorInspectorStateOperations _inspectorState=new();
    private static void CopyArray(GArray target,GArray source){var copy=source.Duplicate();target.Clear();foreach(var value in copy)target.Add(value);}
    public Resource capture_scene_data(Control owner,bool duplicate)
    {
        var model=Model(owner);var canvas=owner.Get("canvas").As<Control>();string section=model.Get("selected_section_id").AsString();if(canvas!=null&&section.Length>0)owner.Get("_timeline_section_states").AsGodotDictionary()[section]=new Settings{["x"]=canvas.Get("scroll_time"),["y"]=canvas.Get("scroll_rows"),["zoom_x"]=canvas.Get("pixels_per_second"),["zoom_y"]=canvas.Get("row_height"),["cursor"]=canvas.Get("playhead"),["snap"]=canvas.Get("snap_enabled")};var scene=new ActorSceneData();foreach(string name in new[]{"actors","clips","sections"}){var array=scene.Get(name).AsGodotArray();foreach(var value in model.Get(name).AsGodotArray())array.Add(duplicate?value.As<Resource>().Duplicate(true):value);}CopyArray(scene.Get("selected_ids").AsGodotArray(),model.Get("selected_ids").AsGodotArray());foreach(string name in new[]{"selected_id","selected_layer","selected_section_id","focused_actor_id","overlay_actor_id"})scene.Set(name,model.Get(name));scene.Set("playhead_time",canvas!=null?canvas.Get("playhead"):model.Get("playhead_time"));scene.Set("overlay_path",(string[])model.Get("overlay_path").AsStringArray().Clone());scene.Set("section_navigation",_timeline.navigation_state(model));scene.Set("timeline_section_states",owner.Get("_timeline_section_states").AsGodotDictionary().Duplicate(true));scene.Set("inspector_state",owner.Get("inspector_ui_state").As<Resource>().Duplicate(true));var keyframeView=owner.Get("keyframe_view").As<Control>();scene.Set("keyframe_view_enabled",keyframeView!=null&&keyframeView.Visible);scene.Set("video_duration",video_duration(owner));scene.Set("video_duration_custom",owner.Get("_video_duration_override").AsDouble()>0);var editor=owner.Get("keyframe_editor").As<Control>();if(editor!=null){var lanes=editor.Get("lanes").As<Control>();if(lanes!=null){CopyArray(scene.Get("selected_key_ids").AsGodotArray(),lanes.Get("selected_keys").AsGodotArray());scene.Set("keyframe_track_scroll",editor.Get("track_scroll").As<ScrollContainer>().ScrollVertical);scene.Set("keyframe_detail_scroll",editor.Get("detail_scroll").As<ScrollContainer>().ScrollHorizontal);}}if(owner.GetParent() is SplitContainer split)scene.Set("timeline_split_offset",split.SplitOffsets.Length>0?split.SplitOffsets[0]:0);var camera=owner.GetNodeOrNull<Node3D>("../../../../World/SubViewport/Freecam");if(camera!=null){scene.Set("editor_camera_transform",camera.Transform);var head=camera.GetNodeOrNull<Node3D>("Head");var lens=camera.GetNodeOrNull<Camera3D>("Head/Camera3D");if(head!=null)scene.Set("editor_camera_head_rotation",head.Rotation);if(lens!=null)scene.Set("editor_camera_lens_rotation",lens.Rotation);scene.Set("editor_camera_speed",camera.Get("speed"));}return scene;
    }
    public void restore_scene_data(Control owner,Resource? scene,bool retainHistory)
    {
        if(scene==null)return;var model=Model(owner);Canvas(owner).Call("cancel_drag");foreach(string name in new[]{"actors","clips","sections","selected_ids"})CopyArray(model.Get(name).AsGodotArray(),scene.Get(name).AsGodotArray());var sections=model.Get("sections").AsGodotArray();if(sections.Count==0)sections.Add(new ActorSection());foreach(string name in new[]{"selected_id","selected_layer","selected_section_id","focused_actor_id","playhead_time","overlay_actor_id"})model.Set(name,scene.Get(name));if(_timeline.section_for_id(model,model.Get("selected_section_id").AsString())==null)model.Set("selected_section_id",sections[0].As<Resource>().Get("id"));model.Set("overlay_path",(string[])scene.Get("overlay_path").AsStringArray().Clone());_timeline.restore_navigation_state(model,scene.Get("section_navigation").AsGodotDictionary());owner.Set("_video_duration_override",scene.Get("video_duration_custom").AsBool()?Math.Max(.01,scene.Get("video_duration").AsDouble()):-1);var history=model.Get("history").As<UndoRedo>();if(!retainHistory&&GodotObject.IsInstanceValid(history)){history.ClearHistory();history.Free();}model.Set("history",new UndoRedo());owner.Set("_timeline_section_states",scene.Get("timeline_section_states").AsGodotDictionary().Duplicate(true));_inspectorState.restore_from(owner.Get("inspector_ui_state").As<Resource>(),scene.Get("inspector_state").As<Resource>());owner.Set("_displayed_section_id","");owner.Set("_displayed_focus_id","");recreate_runtimes(owner);model.EmitSignal("changed");set_keyframe_view(owner,scene.Get("keyframe_view_enabled").AsBool());var editor=owner.Get("keyframe_editor").As<Control>();if(editor!=null){var lanes=editor.Get("lanes").As<Control>();if(lanes!=null){CopyArray(lanes.Get("selected_keys").AsGodotArray(),scene.Get("selected_key_ids").AsGodotArray());editor.Get("track_scroll").As<ScrollContainer>().ScrollVertical=scene.Get("keyframe_track_scroll").AsInt32();editor.Get("detail_scroll").As<ScrollContainer>().ScrollHorizontal=scene.Get("keyframe_detail_scroll").AsInt32();lanes.QueueRedraw();}}if(owner.GetParent() is SplitContainer split){var offsets=split.SplitOffsets;if(offsets.Length==0)offsets=new int[1];offsets[0]=scene.Get("timeline_split_offset").AsInt32();split.SplitOffsets=offsets;}var camera=owner.GetNodeOrNull<Node3D>("../../../../World/SubViewport/Freecam");if(camera!=null){camera.Transform=scene.Get("editor_camera_transform").AsTransform3D();var head=camera.GetNodeOrNull<Node3D>("Head");var lens=camera.GetNodeOrNull<Camera3D>("Head/Camera3D");if(head!=null)head.Rotation=scene.Get("editor_camera_head_rotation").AsVector3();if(lens!=null)lens.Rotation=scene.Get("editor_camera_lens_rotation").AsVector3();camera.Set("speed",scene.Get("editor_camera_speed"));}
    }
}
